UPDATE /* com.seinfo.protoA.component.admin.mapper.AdminMapper.updateProposalState */
       seinfo_request
   SET request_state = #{requestState}
     , mod_user_id = #{userEmail}
     , mod_dt = now()

    , request_accept_d = now()


    , request_complete_d = now()

 WHERE request_no = #{requestNo}
